// Shape the failure for the audit trail and for whatever alerting is wired up
// later. This node talks to nothing outside the host and never retries the
// workflow that failed - see the WF-99 row in docs/workflows.md.

const MAX_MESSAGE = 500;

// Credentials must never reach an alert or the audit trail (docs/security.md).
// Order matters. The scheme rules (Bearer/Basic/Token) must run before the
// generic key=value rule: otherwise the generic rule consumes the word "Bearer"
// as if it were the value and leaves the actual token in the message.
function redact(text) {
  if (typeof text !== 'string') return '';
  return text
    .replace(/\b([a-z][a-z0-9+.-]*):\/\/([^:\s/@]+):([^@\s]+)@/gi, '$1://$2:***@')
    .replace(/\beyJ[A-Za-z0-9._-]{16,}/g, '***jwt***')
    .replace(/\b(Bearer|Basic|Token)\s+[A-Za-z0-9._~+/=-]{6,}/gi, '$1 ***')
    .replace(
      /\b(password|passwd|pwd|secret|token|api[_-]?key|authorization)\b(\s*[:=]\s*)(?:(?:Bearer|Basic|Token)\s+)?("?)[^\s,;"')]+\3/gi,
      '$1$2***',
    );
}

function clip(text) {
  return text.length > MAX_MESSAGE ? text.slice(0, MAX_MESSAGE) + ' ... [truncated]' : text;
}

// The deduplication identity for this failure (0011_notifications.sql).
//
// A schedule that fails every 15 minutes must produce ONE alert, not 96, and
// the thing that makes two failures "the same" is the workflow, the node and
// the shape of the message - never the message itself. A timeout that names a
// different company, or a row count that ticks up, is the same fault. So the
// message is reduced to a fingerprint: identifiers and numbers out, structure
// left in.
function fingerprint(text) {
  return String(text)
    .replace(/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi, '<uuid>')
    .replace(/\b\d[\d.,:]*/g, '<n>')
    .replace(/\s+/g, ' ')
    .trim()
    .slice(0, 160);
}

const src = $input.first().json ?? {};
const execution = src.execution ?? {};
const workflow = src.workflow ?? {};

// The stack trace is deliberately dropped. It is in the n8n execution already,
// and it is the most likely place for a connection string to appear.
const message = clip(redact(execution.error?.message ?? 'Workflow failed with no error message'));
const failedNode = execution.lastNodeExecuted ?? '';

return [
  {
    json: {
      execution_id: execution.id === undefined || execution.id === null ? '' : String(execution.id),
      execution_url: execution.url ?? '',
      execution_mode: execution.mode ?? '',
      retry_of: execution.retryOf ?? null,
      workflow_id: workflow.id ?? '',
      workflow_name: workflow.name ?? '',
      failed_node: failedNode,
      error_message: message,
      // What goes into agent_runs.error.
      error: failedNode ? failedNode + ': ' + message : message,
      dedup_key: 'agent_failure:' + (workflow.id ?? 'unknown') + ':' +
        (failedNode || 'unknown') + ':' + fingerprint(message),
      failed_at: new Date().toISOString(),
    },
  },
];

